#pragma once
#include <algorithm>
#include <memory>
namespace dsa { template<class T> class AvlTree { struct Node{T value;int height{1};std::unique_ptr<Node> left,right;explicit Node(T v):value(std::move(v)){} };std::unique_ptr<Node> root_;static int h(const std::unique_ptr<Node>&n){return n?n->height:0;}static void fix(Node&n){n.height=1+std::max(h(n.left),h(n.right));}static std::unique_ptr<Node> rotate_left(std::unique_ptr<Node> n){auto r=std::move(n->right);n->right=std::move(r->left);r->left=std::move(n);fix(*r->left);fix(*r);return r;}static std::unique_ptr<Node> rotate_right(std::unique_ptr<Node> n){auto l=std::move(n->left);n->left=std::move(l->right);l->right=std::move(n);fix(*l->right);fix(*l);return l;}static std::unique_ptr<Node> add(std::unique_ptr<Node>n,T v){if(!n)return std::make_unique<Node>(std::move(v));if(v<n->value)n->left=add(std::move(n->left),std::move(v));else if(n->value<v)n->right=add(std::move(n->right),std::move(v));else return n;fix(*n);int b=h(n->left)-h(n->right);if(b>1){if(h(n->left->left)<h(n->left->right))n->left=rotate_left(std::move(n->left));return rotate_right(std::move(n));}if(b<-1){if(h(n->right->right)<h(n->right->left))n->right=rotate_right(std::move(n->right));return rotate_left(std::move(n));}return n;}public:void insert(T v){root_=add(std::move(root_),std::move(v));}bool contains(const T&v)const{auto*n=root_.get();while(n){if(v<n->value)n=n->left.get();else if(n->value<v)n=n->right.get();else return true;}return false;}}; }
